/* ============================================================
   CONTENU PÉDAGOGIQUE — c'est le seul fichier à modifier pour
   ajouter ou corriger des leçons et des exercices.

   Types d'étapes :
     lecon   : { t, titre, texte (HTML), code? (exemple exécutable) }
     qcm     : { t, q, code?, choix:[...], bon: indice, expl }
     predire : { t, code, attendu, expl }
     ordre   : { t, q, lignes:[...dans le bon ordre], attendu, expl? }
     code    : { t, titre, enonce (HTML), depart, solution, d (1 à 3),
                 tests:[{ entrees?:[...], sortie?:"...", appels?:[[expression, valeur attendue]] }],
                 indices:[...],
                 requis?:[...], interdit?:[...]   mots (for, while, if, def, return, import), opérateurs
                                                  (*, %, //, **...), nombres ou noms, cherchés dans la
                                                  structure du programme et non dans son texte,
                 depend?:{ variable: [noms] }     la variable doit être calculée à partir de ces noms,
                 caches?:[...]                    tests supplémentaires non montrés dans l'énoncé :
                                                  listes de saisies, ou appels de fonction ; le résultat
                                                  attendu est celui de la solution }

   Conseil : ajoutez les nouvelles étapes À LA FIN d'un chapitre,
   la progression des élèves est enregistrée par position.
   ============================================================ */

const table = n => Array.from({ length: 10 }, (_, k) => `${n} x ${k + 1} = ${n * (k + 1)}`).join("\n");
const fizz = n => Array.from({ length: n }, (_, k) => { k++; return k % 15 === 0 ? "FizzBuzz" : k % 3 === 0 ? "Fizz" : k % 5 === 0 ? "Buzz" : k; }).join("\n");

