        depart: `from random import randint\n\ndef somme_des():\n    `,
        solution: `from random import randint\n\ndef somme_des():\n    return randint(1, 6) + randint(1, 6)`,
        tests: [{ appels: [
          ["all(2 <= somme_des() <= 12 for _ in range(300))", "True", "La somme est toujours comprise entre 2 et 12"],
          ["sum(somme_des() == 7 for _ in range(6000)) > 800", "True", "Sur 6000 lancers, la somme 7 sort environ une fois sur six"]] }],
